    [FunctionalFact]
    public async Task GivenConcurrentNativeProofs_WhenOpening_ThenOneWinnerAndLostResponseRequiresFreshChallenge()
    {using var client=new ProtectionFixture();using var scoped=new ProtectionFixture();var s=await Setup(client);var p=await Add(s,client,scoped);var c=await Challenge(s,p.PublicId);var proof=scoped.Sign(c.Challenge);var results=await Task.WhenAll(Open(s,p.PublicId,c.Challenge,proof),Open(s,p.PublicId,c.Challenge,proof));try{Assert.Single(results,x=>x.StatusCode==HttpStatusCode.OK);await Failure(Assert.Single(results,x=>x.StatusCode!=HttpStatusCode.OK),401);}finally{foreach(var r in results)r.Dispose();}var next=await Challenge(s,p.PublicId);using var retry=await Open(s,p.PublicId,next.Challenge,scoped.Sign(next.Challenge));await Success<OpenProfileAccessOutput>(retry,200);await using var db=fixture.Context();Assert.Equal(2,await db.VaultAccessSessions.CountAsync(x=>x.AccountId==s.InternalId && x.ProfileId==p.Id));}
    [FunctionalFact]
    public async Task GivenPostConsumptionSessionFailure_WhenOpening_Then503RollsBackAndSameProofRetries()
    {using var client=new ProtectionFixture();using var scoped=new ProtectionFixture();var s=await Setup(client);var p=await Add(s,client,scoped);var c=await Challenge(s,p.PublicId);var proof=scoped.Sign(c.Challenge);var before=await SecuritySnapshot(s);await using var db=fixture.Context();await db.Database.ExecuteSqlRawAsync("CREATE FUNCTION cerberus.reject_profile_access_fixture() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.profile_id IS NOT NULL THEN RAISE EXCEPTION 'synthetic session outage' USING ERRCODE='08006'; END IF; RETURN NEW; END $$; CREATE TRIGGER reject_profile_access_fixture BEFORE INSERT ON cerberus.vault_access_session FOR EACH ROW EXECUTE FUNCTION cerberus.reject_profile_access_fixture();");try{using var response=await Open(s,p.PublicId,c.Challenge,proof);await Failure(response,503,"persistence_unavailable");Assert.Equal(before,await SecuritySnapshot(s));}finally{await db.Database.ExecuteSqlRawAsync("DROP TRIGGER IF EXISTS reject_profile_access_fixture ON cerberus.vault_access_session; DROP FUNCTION IF EXISTS cerberus.reject_profile_access_fixture();");}using var retry=await Open(s,p.PublicId,c.Challenge,proof);await Success<OpenProfileAccessOutput>(retry,200);}
    [FunctionalTheory][InlineData(false)][InlineData(true)]
    public async Task GivenUnavailableDatabaseDependency_WhenChallengingOrOpening_Then503(bool open)
    {using var client=new ProtectionFixture();using var scoped=new ProtectionFixture();var s=await Setup(client);var p=await Add(s,client,scoped);var c=open?await Challenge(s,p.PublicId):null;var before=await SecuritySnapshot(s);await using var db=fixture.Context();await db.Database.ExecuteSqlRawAsync("ALTER TABLE cerberus.profile RENAME TO fixture_unavailable_profile");try{using var response=open?await Open(s,p.PublicId,c!.Challenge,scoped.Sign(c.Challenge)):await Gateway.Client.SendAsync(Request(s,p.PublicId,false,ChallengeBody()));await Failure(response,503);}finally{await db.Database.ExecuteSqlRawAsync("ALTER TABLE cerberus.fixture_unavailable_profile RENAME TO profile");}Assert.Equal(before,await SecuritySnapshot(s));}
    private static TheoryData<bool,string> Pairs(params string[] names){var cases=new TheoryData<bool,string>();foreach(var open in new[]{false,true})foreach(var n in names)cases.Add(open,n);return cases;}
    private static string Hash(byte[] bytes)=>ProtocolBinary.Encode(SHA256.HashData(bytes));
    private static byte[] ChallengeBody()=>JsonSerializer.SerializeToUtf8Bytes(new{expectedRevision=1,requestHash=Hash(Raw)});
    private static HttpRequestMessage Request(State s,Guid id,bool open,byte[] body)
    {var r=new HttpRequestMessage(HttpMethod.Post,"/api/profiles/"+id+"/access"+(open?"":"/challenges")){Content=new ByteArrayContent(body)};r.Content.Headers.ContentType=new("application/json"){CharSet="utf-8"};r.Headers.Authorization=new("Bearer",RegistrationApiFixture.Token(s.Actor));if(open){r.Headers.Add("X-Cerberus-Challenge-Id",Guid.NewGuid().ToString());r.Headers.Add("X-Cerberus-Proof",ProtocolBinary.Encode(new byte[64]));}return r;}
    private async Task<IssueProfileAccessChallengeOutput> Challenge(State s,Guid id){using var request=Request(s,id,false,ChallengeBody());using var r=await Gateway.Client.SendAsync(request);var output=await Success<IssueProfileAccessChallengeOutput>(r,201);AssertFields(output,"challenge","profile");AssertFields(output.Profile,"accountId","envelope","keyWrappers","profileId","revision");return output;}
    private async Task<HttpResponseMessage> Open(State s,Guid id,VaultProofChallenge challenge,string proof,byte[]? raw=null){using var r=Request(s,id,true,raw??Raw);r.Headers.Remove("X-Cerberus-Challenge-Id");r.Headers.Remove("X-Cerberus-Proof");r.Headers.Add("X-Cerberus-Challenge-Id",challenge.ChallengeId.ToString());r.Headers.Add("X-Cerberus-Proof",proof);return await Gateway.Client.SendAsync(r);}
    private async Task<HttpResponseMessage> WithAccess(State s,HttpMethod method,string path,string access,object? body=null){using var r=new HttpRequestMessage(method,path);r.Headers.Authorization=new("Bearer",RegistrationApiFixture.Token(s.Actor));r.Headers.Add("X-Cerberus-Vault-Access",access);if(body is not null)r.Content=JsonContent.Create(body);return await Gateway.Client.SendAsync(r);}
    private static async Task<T> Success<T>(HttpResponseMessage r,int status) where T:class{Assert.Equal((HttpStatusCode)status,r.StatusCode);Assert.True(r.Headers.CacheControl?.NoStore);var output=await r.Content.ReadFromJsonAsync<DataOutput<T>>();Assert.True(output!.Success);return Assert.IsType<T>(output.Data);}
    private static void AssertFields(object value,params string[] names){using var d=JsonDocument.Parse(JsonSerializer.Serialize(value,ProtectionFixture.Json));Assert.Equal(names.Order(),d.RootElement.EnumerateObject().Select(x=>x.Name).Order());}
    private async Task<string> SecuritySnapshot(State s){await using var db=fixture.Context();return JsonSerializer.Serialize(new{Content=await Snapshot(s),Account=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==s.InternalId),Sessions=await db.VaultAccessSessions.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Challenges=await db.VaultUnlockChallenges.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync()});}
    private sealed record State(Guid Actor,Guid AccountId,long InternalId,string Access);
    private sealed record ResourceSet(VaultRecord Record,VaultFolder Folder,VaultCollection Collection);
    private async Task<State> Setup(ProtectionFixture client)
    {var actor=Guid.NewGuid();fixture.Users[actor+"@example.test"]=new(actor,"fixture-password");await using var db=fixture.Context();var a=new Account{PublicId=Guid.NewGuid(),HeimdallPublicId=actor,DetailsEnvelope=JsonSerializer.SerializeToUtf8Bytes(Envelope(),ProtectionFixture.Json)};db.Accounts.Add(a);await db.SaveChangesAsync();var access=ProtectionFixture.Encode(RandomNumberGenerator.GetBytes(32));OpaqueAccessHandle.TryHash(access,out var verifier);db.VaultProtections.Add(new(){AccountId=a.Id,Material=JsonSerializer.SerializeToUtf8Bytes(client.Material,ProtectionFixture.Json)});db.VaultAccessSessions.Add(new(){AccountId=a.Id,HandleVerifier=verifier,IssuedAt=DateTimeOffset.UtcNow.AddMinutes(-1),ExpiresAt=DateTimeOffset.UtcNow.AddHours(1),PolicyRevision=1,RevocationGeneration=1});await db.SaveChangesAsync();return new(actor,a.PublicId,a.Id,access);}
    private async Task<ResourceSet> Items(State s)
    {var bytes=JsonSerializer.SerializeToUtf8Bytes(Envelope(),ProtectionFixture.Json);var now=DateTimeOffset.FromUnixTimeMilliseconds(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());var record=new VaultRecord{PublicId=Guid.NewGuid(),AccountId=s.InternalId,Envelope=bytes,EditedAt=now};var folder=new VaultFolder{PublicId=Guid.NewGuid(),AccountId=s.InternalId,Envelope=bytes,EditedAt=now};var collection=new VaultCollection{PublicId=Guid.NewGuid(),AccountId=s.InternalId,Envelope=bytes,EditedAt=now};await using var db=fixture.Context();db.Records.Add(record);db.Folders.Add(folder);db.Collections.Add(collection);await db.SaveChangesAsync();return new(record,folder,collection);}
    private async Task<CollectionGrant> Grant(State owner,ProtectionFixture author,State recipient,ProtectionFixture client,VaultCollection collection,CollectionGrantAccess access=CollectionGrantAccess.ReadOnly)
    {var id=Guid.NewGuid();var grant=new CollectionGrant{PublicId=id,CollectionId=collection.Id,RecipientAccountId=recipient.InternalId,Access=access,RecipientKeyEnvelope=JsonSerializer.SerializeToUtf8Bytes(author.WrapGrant(owner.AccountId,collection.PublicId,id,recipient.Actor,client.Material.RecipientKey),ProtectionFixture.Json)};await using var db=fixture.Context();db.CollectionGrants.Add(grant);await db.SaveChangesAsync();return grant;}
    private async Task<Profile> Add(State s,ProtectionFixture client,ProtectionFixture scoped,ProfileAssociationInput? ids=null,string mode="Master")
    {var id=Guid.NewGuid();var input=new ProfileCreateInput(id,Envelope(),new(mode,scoped.Material.UnlockVerifier,client.Wrap(s.AccountId,"profile",id,s.Actor),mode=="PerProfile"?scoped.Material.PasswordWrapper:null),DateTimeOffset.UtcNow,ids?.RecordIds??[],ids?.FolderIds??[],ids?.CollectionIds??[]);using var request=new HttpRequestMessage(HttpMethod.Post,"/api/profiles"){Content=JsonContent.Create(input)};request.Headers.Authorization=new("Bearer",RegistrationApiFixture.Token(s.Actor));request.Headers.Add("X-Cerberus-Vault-Access",s.Access);using var response=await Gateway.Client.SendAsync(request);Assert.Equal(HttpStatusCode.Created,response.StatusCode);await using var db=fixture.Context();return await db.Profiles.AsNoTracking().SingleAsync(x=>x.PublicId==id);}
    private static EncryptedEnvelope Envelope()=>new("cerberus-content-v1",1,ProtectionFixture.Encode(RandomNumberGenerator.GetBytes(32)),ProtectionFixture.Encode(RandomNumberGenerator.GetBytes(12)),"AQID",ProtectionFixture.Encode(new byte[16]));
    private async Task<string> Content(State s,State foreign){await using var db=fixture.Context();var owners=new[]{s.InternalId,foreign.InternalId};return JsonSerializer.Serialize(new{Records=await db.Records.AsNoTracking().Where(x=>owners.Contains(x.AccountId)).OrderBy(x=>x.Id).ToArrayAsync(),Folders=await db.Folders.AsNoTracking().Where(x=>owners.Contains(x.AccountId)).OrderBy(x=>x.Id).ToArrayAsync(),Collections=await db.Collections.AsNoTracking().Where(x=>owners.Contains(x.AccountId)).OrderBy(x=>x.Id).ToArrayAsync(),Grants=await db.CollectionGrants.AsNoTracking().Where(x=>owners.Contains(x.RecipientAccountId)).OrderBy(x=>x.Id).ToArrayAsync()});}
    private async Task<string> Snapshot(State s){await using var db=fixture.Context();var profiles=await db.Profiles.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync();var ids=profiles.Select(x=>x.Id).ToArray();return JsonSerializer.Serialize(new{Profiles=profiles,Records=await db.ProfileRecords.AsNoTracking().Where(x=>ids.Contains(x.ProfileId)).OrderBy(x=>x.ProfileId).ThenBy(x=>x.RecordId).ToArrayAsync(),Folders=await db.ProfileFolders.AsNoTracking().Where(x=>ids.Contains(x.ProfileId)).OrderBy(x=>x.ProfileId).ThenBy(x=>x.FolderId).ToArrayAsync(),Collections=await db.ProfileCollections.AsNoTracking().Where(x=>ids.Contains(x.ProfileId)).OrderBy(x=>x.ProfileId).ThenBy(x=>x.CollectionId).ToArrayAsync()});}
    private static async Task Failure(HttpResponseMessage response,int status,string? error=null){Assert.Equal((HttpStatusCode)status,response.StatusCode);Assert.True(response.Headers.CacheControl?.NoStore);if(status==413){Assert.Equal("",await response.Content.ReadAsStringAsync());return;}using var doc=JsonDocument.Parse(await response.Content.ReadAsStringAsync());Assert.False(doc.RootElement.GetProperty("success").GetBoolean());if(doc.RootElement.TryGetProperty("data",out var data))Assert.Equal(JsonValueKind.Null,data.ValueKind);if(error is not null)Assert.Contains(error,doc.RootElement.GetProperty("errors").EnumerateArray().Select(x=>x.GetString()));}
    private static string TokenWithIssuedAt(Guid actor,string freshness)
    {
        var claims = new List<Claim> { new("id",actor.ToString()),new("roleId","3"),new("scopeId",RegistrationApiFixture.Scope.ToString()) };
        if (freshness != "missing") claims.Add(new("iat",(DateTimeOffset.UtcNow.ToUnixTimeSeconds()+(freshness == "old" ? -120 : 120)).ToString(),ClaimValueTypes.Integer64));
        return new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken("fixture-issuer","fixture-audience",claims,
            DateTime.UtcNow.AddMinutes(-5),DateTime.UtcNow.AddMinutes(5),new SigningCredentials(new SymmetricSecurityKey(Encoding.ASCII.GetBytes("fixture-only-signing-key-32-characters")),SecurityAlgorithms.HmacSha256)));
    }
